from moler import config  # type: ignore
from typing import Dict, Any

_run_params: Dict[Any, Any] = {}


def merge_params(params1, params2, clone_params=False):
    """
    Function for merging dictionaries - update params1 values by params2
    :param params1: It's source dictionary. Usually procedure_params
    :param params2: It's user dictionary. Usually tc_params
    :param clone_params: If False, params1 is modified, else function operating on copy of params1
    :return merged_params: Merged dictionary
    """
    merged_params = params1
    if clone_params:
        merged_params = params1.copy()

    for key in params2:
        if key in params1:
            _merge_params_body(key, params1, params2, merged_params)
        else:
            msg = "Key {} is not expected. Please check available parameters in procedure_params file".format(key)
            raise KeyError(msg)

    return merged_params


def _merge_params_body(key, params1, params2, merged_params):
    if isinstance(params1[key], type(params2[key])):
        if isinstance(params2[key], dict) and len(params1[key]) == 0:
            merged_params[key] = params2[key]
        elif isinstance(params2[key], dict):
            merge_params(params1[key], params2[key])
        else:
            merged_params[key] = params2[key]
    elif not params1[key] or not params2[key]:
        merged_params[key] = params2[key]
    else:
        msg = "Key {} has wrong type. Should be {} but is {}".format(key, type(params1[key]), type(params2[key]))
        raise TypeError(msg)


def load_run_params(tc_params, golden_params):
    """
    Function returns variables which are available in Robot procedure
    :param tc_params: path to tc_params.env file(supported only yml format) or just params dict
    :param golden_params: path to procedure_params.env file(supported only yml format) or params dict
    :return run_params: return directory. key run_params contains merged procedure_params and tc_params
    """
    global _run_params
    _run_params.clear()

    if not isinstance(tc_params, dict):
        tc_params = config.read_yaml_configfile(path=tc_params)
    if not isinstance(golden_params, dict):
        golden_params = config.read_yaml_configfile(path=golden_params)

    merged_params = merge_params(golden_params, tc_params, clone_params=True)

    _run_params.update(merged_params.copy())

    return _run_params


def get_run_params():
    """
    Function return private value _run_stats.

    :return: _run_params
    """
    return _run_params
